## Why This Is Asked

This question tests CGO binding patterns for asynchronous C callbacks, memory ownership semantics, and safe concurrency when bridging C and Go.

## Key Concepts

- **Asynchronous callbacks**: C calling back into Go with results
- **Memory ownership**: C-allocated JSON via malloc must be freed after copying to Go
- **CGO binding stability**: Managing per-batch contexts safely
- **Concurrency**: Bounded worker pool implementation with correct error propagation

## Code Example

```c
// sim.h
typedef struct { double a, b; int t; } SimInput;
typedef void (*cb_t)(const char* json, size_t len, int status, void* ctx);
void simulate_batch_async(const SimInput* inputs, size_t n, cb_t cb, void* ctx);
```

```go
// sim.go
package sim

import (
    "C"
    "unsafe"
)

type SimInput struct {
    A float64
    B float64
    T int32
}

type result struct {
    json  string
    error error
}

// StartSimulation runs a batch asynchronously, returning channels for results and errors.
func StartSimulation(inputs []SimInput) (<-chan string, <-chan error) {
    results := make(chan string, 1)
    errors := make(chan error, 1)

    cInputs := (*C.SimInput)(C.malloc(C.size_t(len(inputs)) * C.sizeof_SimInput))
    defer C.free(unsafe.Pointer(cInputs))

    for i, inp := range inputs {
        ptr := (*C.SimInput)(unsafe.Pointer(uintptr(unsafe.Pointer(cInputs)) + uintptr(i)*C.sizeof_SimInput))
        ptr.a = C.double(inp.A)
        ptr.b = C.double(inp.B)
        ptr.t = C.int(inp.T)
    }

    ctx := &context{
        results: results,
        errors:  errors,
    }

    C.simulate_batch_async(
        cInputs,
        C.size_t(len(inputs)),
        (C.cb_t)(C.simulate_callback),
        unsafe.Pointer(ctx),
    )

    return results, errors
}

//export simulate_callback
func simulate_callback(json *C.char, len C.size_t, status C.int, ctx unsafe.Pointer) {
    c := (*context)(ctx)
    if status != 0 {
        c.errors <- nil // or wrap status as error
        return
    }
    goBytes := C.GoBytes(unsafe.Pointer(json), C.int(len))
    C.free(unsafe.Pointer(json))
    c.results <- string(goBytes)
}
```

## Why This Is Asked
This question tests end-to-end integration across C and Go in a streaming context, focusing on memory ownership, cross-language callbacks, and safe concurrent use.

## Key Concepts
- **CGO callback bridging**: Safely passing Go functions to C and handling the transition between language runtimes
- **Memory ownership**: Allocating with malloc in C, copying to Go slices, and explicitly freeing C buffers to prevent leaks
- **Streaming/partitioning**: Breaking input into blocks in C and delivering chunks incrementally to Go
- **Concurrency patterns**: Worker pools for processing multiple streams in parallel and proper error propagation through channels

## Code Example

**stream_encrypt.h**
```c
#ifndef STREAM_ENCRYPT_H
#define STREAM_ENCRYPT_H

#include <stddef.h>
#include <stdint.h>

typedef void (*chunk_cb)(const uint8_t* out, size_t out_len, int status, void* ctx);

int stream_encrypt(const uint8_t* in, size_t in_len, chunk_cb cb, void* ctx);

#endif
```

**stream_encrypt.c**
```c
#include "stream_encrypt.h"
#include <stdlib.h>
#include <string.h>

#define BLOCK_SIZE 4096

static void encrypt_block(const uint8_t* in, size_t len, uint8_t** out, size_t* out_len) {
    *out = (uint8_t*)malloc(len);
    memcpy(*out, in, len);
    *out_len = len;
}

int stream_encrypt(const uint8_t* in, size_t in_len, chunk_cb cb, void* ctx) {
    size_t offset = 0;
    while (offset < in_len) {
        size_t block_len = (offset + BLOCK_SIZE > in_len) ? (in_len - offset) : BLOCK_SIZE;
        uint8_t* encrypted = NULL;
        size_t encrypted_len = 0;

        encrypt_block(in + offset, block_len, &encrypted, &encrypted_len);
        cb(encrypted, encrypted_len, 0, ctx);
        free(encrypted);

        offset += block_len;
    }
    return 0;
}
```

**stream_encrypt.go**
```go
package main

/*
#include "stream_encrypt.h"
#include <stdlib.h>

static int call_stream_encrypt(const uint8_t* in, size_t in_len, void* ctx) {
    return stream_encrypt(in, in_len, NULL, ctx);
}
*/
import "C"

import (
    "fmt"
    "sync"
    "unsafe"
)

type StreamResult struct {
    Data []byte
    Err  error
}

var workerPool = make(chan struct{}, 4)

//export chunkCallback
func chunkCallback(out *C.uint8_t, outLen C.size_t, status C.int, ctx unsafe.Pointer) {
    result := (*chan StreamResult)(ctx)
    data := C.GoBytes(unsafe.Pointer(out), C.int(outLen))
    if status != 0 {
        *result <- StreamResult{Err: fmt.Errorf("encryption error: %d", status)}
    } else {
        *result <- StreamResult{Data: data}
    }
}

func StartEncryptStream(input string, key []byte) (<-chan []byte, <-chan error) {
    chunks := make(chan []byte, 10)
    errs := make(chan error, 10)
    resultChan := make(chan StreamResult)

    go func() {
        defer close(chunks)
        defer close(errs)

        workerPool <- struct{}{}
        defer func() { <-workerPool }()

        cInput := C.CString(input)
        defer C.free(unsafe.Pointer(cInput))

        C.stream_encrypt(
            (*C.uint8_t)(unsafe.Pointer(cInput)),
            C.size_t(len(input)),
            (C.chunk_cb)(C.chunkCallback),
            unsafe.Pointer(&resultChan),
        )

        close(resultChan)
    }()

    go func() {
        for result := range resultChan {
            if result.Err != nil {
                errs <- result.Err
            } else {
                chunks <- result.Data
            }
        }
    }()

    return chunks, errs
}

func main() {
    var wg sync.WaitGroup

    for i := 0; i < 2; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            chunks, errs := StartEncryptStream(fmt.Sprintf("message-%d", id), []byte("key"))
            for {
                select {
                case chunk, ok := <-chunks:
                    if !ok {
                        return
                    }
                    fmt.Printf("Stream %d: got chunk len=%d\n", id, len(chunk))
                case err, ok := <-errs:
                    if !ok {
                        return
                    }
                    fmt.Printf("Stream %d: error: %v\n", id, err)
                }
            }
        }(i)
    }

    wg.Wait()
}
```

